import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type ComponentNameProps = Record<string, any>;

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#121216",
  transparentBackground = false,
  durationInSeconds = 12,
  ballPrimaryColor = "#ff4d4d",
  rampColor = "#3a3a48",
  accentColor = "#ffffff",
  cameraZoom = 1.6,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Track logic
  const segments = React.useMemo(() => [
    { type: 'line', x0: 150, y0: 250, x1: 850, y1: 350, len: 707 },
    { type: 'bezier', x0: 850, y0: 350, cx: 950, cy: 350, x1: 950, y1: 600, len: 280 },
    { type: 'line', x0: 950, y0: 600, x1: 250, y1: 700, len: 707 },
    { type: 'bezier', x0: 250, y0: 700, cx: 150, cy: 700, x1: 150, y1: 950, len: 280 },
    { type: 'line', x0: 150, y0: 950, x1: 850, y1: 1050, len: 707 },
    { type: 'bezier', x0: 850, y0: 1050, cx: 950, cy: 1050, x1: 950, y1: 1300, len: 280 },
    { type: 'line', x0: 950, y0: 1300, x1: 250, y1: 1400, len: 707 },
    { type: 'bezier', x0: 250, y0: 1400, cx: 150, cy: 1400, x1: 150, y1: 1650, len: 280 }
  ], []);

  const totalPathLen = 3948;
  const ballDiameter = 32;

  // Ball positions staggered exactly along the continuous path 
  const ballStarts = React.useMemo(() => [
    0, 140, 280, 420, 560,
    1050, 1190, 1330, 1470, 1610,
    2050, 2190, 2330, 2470, 2610,
    3050, 3190, 3330, 3470, 3610,
    totalPathLen // Virtual ball 20 (Target)
  ], []);

  const getPointAtDist = React.useCallback((d: number) => {
    let current = 0;
    for (const seg of segments) {
      if (d <= current + seg.len) {
        const t = (d - current) / seg.len;
        if (seg.type === 'line') {
          return {
            x: seg.x0! + t * (seg.x1! - seg.x0!),
            y: seg.y0! + t * (seg.y1! - seg.y0!)
          };
        } else if (seg.type === 'bezier') {
          const invT = 1 - t;
          return {
            x: invT * invT * seg.x0! + 2 * invT * t * seg.cx! + t * t * seg.x1!,
            y: invT * invT * seg.y0! + 2 * invT * t * seg.cy! + t * t * seg.y1!
          };
        }
      }
      current += seg.len;
    }
    const last = segments[segments.length - 1];
    return { x: last.x1!, y: last.y1! };
  }, [segments]);

  // Master Timeline
  const totalFrames = fps * durationInSeconds;
  const motionFrames = Math.max(totalFrames - 45, 1); // Save 1.5s for rest at the end

  let rawT = interpolate(frame, [0, motionFrames], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp'
  });
  const t = Easing.inOut(Easing.ease)(rawT);
  const pulseDist = t * totalPathLen;

  // Calculate Camera Focus
  const activePoint = getPointAtDist(pulseDist);
  const minX = width / (2 * cameraZoom);
  const maxX = width - width / (2 * cameraZoom);
  const minY = height / (2 * cameraZoom);
  const maxY = height - height / (2 * cameraZoom);

  const camX = Math.max(minX, Math.min(activePoint.x, maxX));
  const camY = Math.max(minY, Math.min(activePoint.y, maxY));

  const translateX = width / 2 - camX * cameraZoom;
  const translateY = height / 2 - camY * cameraZoom;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: "hidden" }}>
      <div style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        transform: `translate(${translateX}px, ${translateY}px) scale(${cameraZoom})`,
        transformOrigin: "0 0",
        transition: "none",
        willChange: "transform"
      }}>
        <svg width={width} height={height} style={{ position: 'absolute', overflow: 'visible' }}>
          <defs>
            <pattern id="grid" width="60" height="60" patternUnits="userSpaceOnUse">
              <path d="M 60 0 L 0 0 0 60" fill="none" stroke={accentColor} opacity={0.05} strokeWidth={1} />
            </pattern>
            <filter id="shadow" x="-50%" y="-50%" width="200%" height="200%">
              <feDropShadow dx="0" dy="8" stdDeviation="6" floodColor="#000" floodOpacity="0.4" />
            </filter>
            <linearGradient id="rampGradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={rampColor} />
              <stop offset="100%" stopColor="#111" />
            </linearGradient>
          </defs>

          {/* Background Grid for Sense of Motion */}
          <rect x="-1000" y="-1000" width="4000" height="4000" fill="url(#grid)" />

          {/* Support Pillars */}
          {[150, 850, 950, 250].map((xPos, idx) => (
            <line
              key={`pillar-${idx}`}
              x1={xPos}
              y1={250 + idx * 250 + 28}
              x2={xPos}
              y2={2500}
              stroke={rampColor}
              strokeWidth={16}
              opacity={0.15}
            />
          ))}

          {/* Ramps */}
          {segments.map((seg, i) => {
            if (seg.type === 'line') {
              return (
                <line
                  key={`ramp-${i}`}
                  x1={seg.x0}
                  y1={seg.y0! + 28}
                  x2={seg.x1}
                  y2={seg.y1! + 28}
                  stroke={rampColor}
                  strokeWidth={24}
                  strokeLinecap="round"
                />
              );
            }
            return null;
          })}

          {/* Final Cup (Wider to accommodate larger final ball) */}
          <path
            d="M 80 1570 L 90 1665 Q 150 1685 210 1665 L 220 1570"
            fill="none"
            stroke={rampColor}
            strokeWidth={14}
            strokeLinecap="round"
            strokeLinejoin="round"
          />

          {/* Success Text positioned below the bin */}
          <text
            x={150}
            y={1740}
            fontSize={40}
            fontWeight="bold"
            fill={accentColor}
            textAnchor="middle"
          >
            success
          </text>

          {/* Render 20 Balls */}
          {Array.from({ length: 20 }).map((_, i) => {
            const isLast = i === 19;
            const startS = ballStarts[i];
            const nextS = ballStarts[i + 1];
            const endS = isLast ? totalPathLen : nextS - ballDiameter;

            let currentDist = startS;

            if (pulseDist > startS && pulseDist <= nextS) {
              const localT = (pulseDist - startS) / (nextS - startS);
              currentDist = startS + localT * (endS - startS);
            } else if (pulseDist > nextS) {
              currentDist = endS;
            }

            const pos = getPointAtDist(currentDist);
            const travel = currentDist - startS;
            
            // Adjust dimensions for the final ball
            const bDiam = isLast ? 80 : ballDiameter;
            const rOuter = isLast ? 40 : 16;
            const rInner = isLast ? 30 : 9;
            const yOffset = isLast ? -24 : 0; // Shift up so larger ball sits properly on visual track
            
            const rotation = (travel / (Math.PI * bDiam)) * 360;

            return (
              <g
                key={`ball-${i}`}
                transform={`translate(${pos.x}, ${pos.y + yOffset}) rotate(${rotation})`}
                filter="url(#shadow)"
              >
                <circle r={rOuter} fill={ballPrimaryColor} />
                <circle r={rInner} cx={0} cy={0} fill={accentColor} />
                {/* Rolling indicator markings / Number Text */}
                <text
                  x={0}
                  y={isLast ? 6 : 3.5}
                  fontSize={isLast ? 18 : 10}
                  fontWeight="bold"
                  textAnchor="middle"
                  fill="#000"
                  transform={isLast ? `rotate(${-rotation})` : undefined} // Counter-rotate to keep readable
                >
                  {i + 1}
                </text>
              </g>
            );
          })}
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default ComponentName;